-- Table: public.acc_chart_account

CREATE TABLE public.acc_chart_account (
    id integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1073)  NOT NULL,
    parent_id integer,
    code character varying(50) NOT NULL,
    name character varying(250) NOT NULL,
    is_group boolean DEFAULT false NOT NULL,
    state_id smallint NOT NULL,
    created_date timestamp without time zone DEFAULT now() NOT NULL,
    account_type_id smallint,
    is_quantity boolean DEFAULT false NOT NULL,
    is_currency boolean DEFAULT false NOT NULL,
    CONSTRAINT acc_chart_account_pkey PRIMARY KEY (id),
    CONSTRAINT acc_chart_account_account_type_id_fkey FOREIGN KEY (account_type_id) REFERENCES public.acc_account_type(id),
    CONSTRAINT acc_chart_account_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES public.acc_chart_account(id),
    CONSTRAINT acc_chart_account_state_id_fkey FOREIGN KEY (state_id) REFERENCES public.cmn_state(id)
);


CREATE INDEX idx_acc_chart_account_account_type_id ON public.acc_chart_account USING btree (account_type_id);

CREATE INDEX idx_acc_chart_account_parent_id ON public.acc_chart_account USING btree (parent_id);

CREATE INDEX idx_acc_chart_account_state_id ON public.acc_chart_account USING btree (state_id);
